    with _c(path) as c:
        rows = c.execute(
            "SELECT category, SUM(amount) FROM events WHERE strftime('%Y-%m-%d', ts, 'unixepoch') = ? GROUP BY category",
            (day,)).fetchall()
    return {k: v for k, v in rows}
